// AWI: sisa teks harga TiTAN di beranda + artikel 10833, plus diagnosa schema (sementara, hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tfix8', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			$c = get_post_field('post_content', 10496); $o = $c;
			$c = preg_replace_callback('#(BYD TiTAN 7 DM</p>\s*<p[^>]*>)SUV PHEV 7 kursi, FWD (?:&amp;|&) AWD, segera hadir(</p>\s*<p[^>]*><strong[^>]*>)Harga diumumkan saat peluncuran#s', function ($m) { return $m[1] . 'SUV PHEV 7 kursi, FWD &amp; AWD, resmi meluncur' . $m[2] . 'Mulai Rp639 jt (OTR Jakarta)'; }, $c, -1, $n); $out['home_card'] = $n;
			$c = str_replace('Harga resmi Indonesia diumumkan saat peluncuran. Ketentuan inden mengikuti kebijakan BYD.', 'Harga resmi BYD TiTAN 7 DM (OTR Jakarta): Rp639 juta (Premium) dan Rp739 juta (Performance); harga OTR Makassar via AWI. Harga BYD Atto 2 diumumkan saat peluncuran. Ketentuan inden mengikuti kebijakan BYD.', $c, $n); $out['home_note'] = $n;
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10496)); clean_post_cache(10496); $out['saved_home'] = 1; }
			$c2 = get_post_field('post_content', 10833); $o2 = $c2;
			$c2 = str_replace('Harga resmi diumumkan saat launching 20 November 2026. Inden sudah dibuka di BYD Haka Karebosi Makassar; hubungi Sales Consultant AWI untuk harga OTR Makassar resmi begitu diumumkan.', 'Harga resmi BYD TiTAN 7 DM (OTR Jakarta) Rp639 juta untuk Premium FWD dan Rp739 juta untuk Performance AWD, diumumkan saat peluncuran 20 November 2026. Unit bisa dipesan di BYD Haka Karebosi Makassar; hubungi Sales Consultant AWI untuk harga OTR Makassar resmi.', $c2, $n); $out['p10833_faq'] = $n;
			if ($c2 !== $o2) { $wpdb->update($wpdb->posts, array('post_content' => $c2), array('ID' => 10833)); clean_post_cache(10833); $out['saved_10833'] = 1; }
			$t = $wpdb->prefix . 'snippets';
			$rows = $wpdb->get_results("SELECT id, name, active, code FROM $t WHERE code LIKE '%ld+json%' OR code LIKE '%ob_start%' OR code LIKE '%wpseo_json_ld%' OR code LIKE '%wpseo_schema%'");
			foreach ($rows as $r) {
				$ctx = array();
				foreach (array('ob_start', 'preg_replace', 'wpseo_json_ld', 'wpseo_schema', 'ld+json') as $k) { $i = strpos($r->code, $k); if ($i !== false) $ctx[] = $k . '@' . $i . ': ' . substr(preg_replace('/\s+/', ' ', $r->code), max(0, $i - 60), 220); }
				$out['snips'][] = $r->id . ' [' . $r->active . '] ' . $r->name . ' | ' . implode(' || ', array_slice($ctx, 0, 3));
			}
			wp_cache_flush();
			return $out;
		},
	));
});
